// Program.cs
app.Use(async (context, next) =>
{
    // Before next middleware
    var sw = Stopwatch.StartNew();
    context.Response.Headers["X-Response-Time"] = sw.ElapsedMilliseconds.ToString();

    await next(); // Call next middleware

    // After next middleware
    sw.Stop();
    context.Response.Headers["X-Response-Time"] = sw.ElapsedMilliseconds.ToString();
});

app.MapControllers();
app.Run();

public class RequestTimingMiddleware(RequestDelegate next, ILogger<RequestTimingMiddleware> logger)
{
    private readonly RequestDelegate _next = next;
    private readonly ILogger<RequestTimingMiddleware> _logger = logger;

    public async Task InvokeAsync(HttpContext context)
    {
        var sw = Stopwatch.StartNew();
        _logger.LogInformation("Incoming request: {Method} {Path}",
            context.Request.Method, context.Request.Path);
        await _next(context);
        sw.Stop();
        _logger.LogInformation("Response time: {Elapsed}ms for {Path}",
            sw.ElapsedMilliseconds, context.Request.Path);
    }
}

// Extension method for clean registration
public static class MiddlewareExtensions
{
    public static IApplicationBuilder UseRequestTiming(this IApplicationBuilder builder)
    {
        return builder.UseMiddleware<RequestTimingMiddleware>();
    }
}

// Program.cs
app.UseRequestTiming();
app.MapControllers();
app.Run();
